//! Conditional-mean econometric models. Public specification: MathWorks arima,
//! estimate/infer/forecast/simulate/summarize and aicbic documentation. Numerical
//! references: Box, Jenkins & Reinsel (1994), Hamilton (1994); independent
//! NumPy/SciPy fixtures are generated by tool/refs/econ/arima.py.
mod arima;
mod composite;
mod display;
mod estimate;
mod forecast;
mod likelihood;
pub(super) mod optimizer;
use super::{Engine, Execution, Value};
use crate::{Array, CellArray, Matrix, Result, StructArray};
pub(super) use arima::Model;
pub(super) use arima::assign;
pub(super) use composite::sync_variance;
pub(super) use display::{body, property};
use std::{collections::BTreeMap, sync::Arc};
pub(super) const NAMES: &[&str] = &[
    "arima",
    "estimate",
    "forecast",
    "infer",
    "simulate",
    "summarize",
    "aicbic",
];
const MAX_LAG: usize = 256;
const MAX_PARAMETERS: usize = 128;
const MAX_ELEMENTS: usize = 2_000_000;
pub(super) fn handles(n: &str) -> bool {
    matches!(n, "arima" | "aicbic")
}
pub(super) fn method(n: &str) -> bool {
    NAMES.contains(&n) && !handles(n)
}
/// Gate on the syntax before evaluating arguments: shared method names (garch,
/// classdef methods) must not evaluate the arguments twice when the first one is not
/// an arima model. Other first-argument forms reach the evaluated-values path.
pub(super) fn expression_method(
    e: &mut Engine,
    n: &str,
    a: &[crate::syntax::Expr],
) -> Result<bool> {
    use crate::syntax::Expr;
    if handles(n) {
        return Ok(true);
    }
    if !method(n) {
        return Ok(false);
    }
    match a.first() {
        Some(Expr::Name(v)) => Ok(e
            .array(v)
            .is_some_and(|v| super::objects::arima_value(e, &Value::from(v)).is_some())),
        Some(Expr::Call(c, a)) => Ok(!e.contains_array(c)
            && e.resolve_function(c)?.is_none()
            && (c == "arima" || (c == "estimate" && expression_method(e, c, a)?))),
        _ => Ok(false),
    }
}
pub(super) fn accepts(e: &Engine, n: &str, a: &[Value]) -> bool {
    handles(n)
        || (method(n)
            && a.first()
                .and_then(|v| super::objects::arima_value(e, v))
                .is_some())
}
pub(super) fn call(
    e: &mut Engine,
    n: &str,
    a: &[Value],
    nout: usize,
    out: &mut Execution,
) -> Result<Vec<Value>> {
    let result = call_inner(e, n, a, nout, out);
    result.map_err(|message| {
        if message.starts_with("econ:") {
            let id = message
                .split_once(": ")
                .map_or("econ:arima:InvalidInput", |s| s.0)
                .to_owned();
            e.raise(message, id)
        } else {
            message
        }
    })
}
fn call_inner(
    e: &mut Engine,
    n: &str,
    a: &[Value],
    nout: usize,
    out: &mut Execution,
) -> Result<Vec<Value>> {
    e.check_cancel()?;
    let max = match n {
        "estimate" => 4,
        "forecast" | "infer" | "simulate" | "aicbic" => 3,
        _ => 1,
    };
    if nout > max {
        return Err(err(n, "TooManyOutputs", "Too many output arguments."));
    }
    let v = if n == "arima" {
        vec![super::objects::arima_new(e, arima::construct(e, a)?)?]
    } else if n == "aicbic" {
        display::aicbic(e, a, nout)?
    } else {
        let m = a
            .first()
            .and_then(|v| super::objects::arima_value(e, v))
            .ok_or_else(|| err(n, "InvalidModel", "First argument must be an arima model."))?;
        match n {
            "estimate" => estimate::estimate(e, &m, &a[1..], out)?,
            "infer" => likelihood::infer(e, &m, &a[1..])?,
            "forecast" | "simulate" => forecast::call(e, n, &m, &a[1..])?,
            "summarize" => {
                if a.len() != 1 {
                    return Err(err(n, "InvalidNumInputs", "Too many input arguments."));
                }
                if nout == 0 {
                    e.emit(out, display::summary_text(&m))?;
                }
                vec![display::summarize(e, &m, a[0].clone())?]
            }
            _ => unreachable!(),
        }
    };
    e.charge_function_outputs(&v)?;
    Ok(v.into_iter().take(nout.max(1)).collect())
}
fn err(n: &str, id: &str, s: &str) -> String {
    format!("econ:{n}:{id}: {s}")
}
fn text(v: &Value) -> Result<String> {
    super::table_fns::text_scalar(v)
        .ok_or_else(|| err("arima", "InvalidText", "Expected scalar text."))
}
fn matrix(e: &Engine, v: &Value) -> Result<Matrix> {
    let a = v.clone().array(&e.cancel)?;
    match a {
        Array::Numeric(m) if m.dims().len() == 2 => Ok(m),
        _ => Err(err(
            "arima",
            "InvalidData",
            "Expected a real double matrix.",
        )),
    }
}
fn scalar(e: &Engine, v: &Value) -> Result<f64> {
    matrix(e, v)?
        .as_scalar()
        .map_err(|_| err("arima", "InvalidScalar", "Expected a real scalar."))
}
fn integer(e: &Engine, v: &Value, lo: usize, hi: usize) -> Result<usize> {
    let x = scalar(e, v)?;
    if !x.is_finite() || x.fract() != 0. || x < lo as f64 || x > hi as f64 {
        Err(err(
            "arima",
            "InvalidOrder",
            "Order or size must be an integer within the supported bounds.",
        ))
    } else {
        Ok(x as usize)
    }
}
fn options(e: &Engine, n: &str, a: &[Value], allowed: &[&str]) -> Result<BTreeMap<String, Value>> {
    if !a.len().is_multiple_of(2) {
        return Err(err(n, "InvalidNameValue", "Expected name-value pairs."));
    }
    let mut o = BTreeMap::new();
    for p in a.as_chunks::<2>().0 {
        let name = text(&p[0])?;
        let canonical = allowed
            .iter()
            .find(|s| s.eq_ignore_ascii_case(&name))
            .ok_or_else(|| err(n, "UnknownOption", &format!("Unknown option '{name}'.")))?;
        // Last value wins, as with the documented name-value syntax.
        let _ = e;
        o.insert((*canonical).into(), p[1].clone());
    }
    Ok(o)
}
fn number(x: f64) -> Array {
    Array::Numeric(Matrix::scalar(x))
}
fn string(e: &Engine, s: &str) -> Result<Array> {
    e.check_cancel()?;
    Ok(Array::Str(crate::StringArray::scalar(s)?))
}
fn row(v: Vec<f64>) -> Result<Array> {
    Ok(Array::Numeric(Matrix::from_column_vec(1, v.len(), v)?))
}
fn column(v: Vec<f64>) -> Result<Array> {
    Ok(Array::Numeric(Matrix::from_column_vec(v.len(), 1, v)?))
}
fn value_matrix(rows: usize, cols: usize, v: Vec<f64>) -> Result<Value> {
    Ok(Value::Matrix(Matrix::from_column_vec(rows, cols, v)?))
}
fn record(e: &Engine, fields: Vec<(&str, Array)>) -> Result<Array> {
    let (names, slots) = fields
        .into_iter()
        .map(|(k, v)| (k.to_owned(), Arc::new(v)))
        .unzip();
    Ok(Array::Struct(StructArray::from_slots(
        1, 1, names, slots, &e.cancel,
    )?))
}
fn cells(e: &Engine, values: &[f64]) -> Result<Array> {
    Ok(Array::Cell(CellArray::from_shared(
        1,
        values.len(),
        values.iter().map(|&v| Arc::new(number(v))).collect(),
        &e.cancel,
    )?))
}
fn coefficients(e: &Engine, v: &Value) -> Result<Vec<f64>> {
    let a = v.clone().array(&e.cancel)?;
    if a.len() > MAX_LAG {
        return Err(err(
            "arima",
            "SizeLimit",
            "Coefficient vectors may contain at most 256 entries.",
        ));
    }
    let result = match a {
        Array::Cell(c) if c.rows() <= 1 || c.cols() <= 1 => (0..c.len())
            .map(|i| scalar(e, &Value::from(c.get_linear(i)?.as_ref().clone())))
            .collect::<Result<Vec<_>>>()?,
        Array::Numeric(m) if m.rows() <= 1 || m.cols() <= 1 => m.data().to_vec(),
        _ => {
            return Err(err(
                "arima",
                "InvalidCoefficients",
                "Expected a numeric vector or cell vector of real scalars.",
            ));
        }
    };
    if result.len() > MAX_LAG || result.iter().any(|x| x.is_infinite()) {
        return Err(err(
            "arima",
            "InvalidCoefficients",
            "Coefficients must be finite or NaN, with at most 256 entries.",
        ));
    }
    Ok(result)
}
fn preflight(e: &Engine, n: usize, paths: usize, copies: usize) -> Result<()> {
    let len = n.checked_mul(paths).ok_or("arima: size overflow")?;
    if len > MAX_ELEMENTS {
        return Err(err(
            "arima",
            "SizeLimit",
            "At most 2000000 elements per output are supported.",
        ));
    }
    e.preflight_elements(len.saturating_mul(copies))
}
